from codec.frame import strip_header

def parse_packet(packet: list, header_len: int) -> list:
    return strip_header(packet, header_len)

files.codec/payload.py:
def copy_payload(body: list) -> list:
    kept = []
    for item in body:
        kept.append(item)
    return kept[1:]

